const inp = $input.first().json || {};
const contacto = String(inp.numero_contacto || '').replace(/\D/g, '');
const wa = String(inp.wa_number || '').replace(/\D/g, '');
const sourceMsgId = String(inp.source_message_id || '').trim();
const dryRun = Boolean(inp.dry_run);

let rawRes = inp.resources;
if (typeof rawRes === 'string') {
  try { rawRes = JSON.parse(rawRes); } catch (e) { rawRes = rawRes.split(',').map(s => s.trim()); }
}
if (!Array.isArray(rawRes) || rawRes.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources es obligatorio y debe ser un array no vacio de "calendar" y/o "zoom".');
}
const validSet = new Set(['calendar', 'zoom']);
for (const r of rawRes) {
  if (!validSet.has(r)) {
    throw new Error(`RECURSOS_INVALIDOS: recurso desconocido "${r}". Solo se permite "calendar" y/o "zoom".`);
  }
}
const unique = Array.from(new Set(rawRes));
const resources = ['calendar', 'zoom'].filter(r => unique.includes(r));
if (resources.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources no contiene recursos validos.');
}

const needCalendar = resources.includes('calendar');
const needZoom = resources.includes('zoom');

const eventoId = String(inp.evento_id || inp.event_id || '').trim();
const zoomId = String(inp.zoom_id || inp.zoom_meeting_id || '').trim();

if (needCalendar && !eventoId) {
  throw new Error('FALTA_EVENTO: evento_id es obligatorio para proponer la cancelacion del recurso calendar.');
}
if (needZoom && !zoomId) {
  throw new Error('FALTA_ZOOM_ID: zoom_id es obligatorio para proponer la cancelacion del recurso zoom.');
}
if (!contacto) {
  throw new Error('FALTA_CONTACTO: numero_contacto es obligatorio.');
}

const payload = {
  wa_number: wa || null,
  contact_number: contacto,
  source_message_id: sourceMsgId || null,
  kind: 'cancel',
  resources,
  event_id: eventoId || null,
  zoom_id: zoomId || null,
  dry_run: dryRun
};

return [{ json: payload }];

const resp = $input.first().json || {};
const prep = $('Preparar Propuesta Cancelacion').first().json || {};
const ok = resp.ok === true;
const proposalId = resp.proposal_id || null;
const state = resp.state || (ok ? 'pending_owner_confirmation' : 'blocked');
const msg = resp.message || (ok
  ? `Propuesta de cancelación de cita (${prep.resources.join(', ')}) enviada a Alek para confirmación.`
  : `No se pudo generar la propuesta de cancelación: ${resp.error || 'error desconocido'}`);

return [{
  json: {
    ok,
    estado: state === 'dry_run' ? 'dry_run' : (ok ? 'propuesta_cancelacion_creada' : 'error_propuesta'),
    state,
    proposal_id: proposalId,
    resources: prep.resources,
    event_id: prep.event_id,
    zoom_id: prep.zoom_id,
    mensaje: msg,
    requires_owner_tap: ok && state === 'pending_owner_confirmation'
  }
}];

const raw = $input.first().json || {};
const headers = raw.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const expected = $env.N8N_CALENDAR_TOKEN;

if (!expected || auth !== `Bearer ${expected}`) {
  throw new Error('AUTH_FAILED: agenda local requiere bearer token valido de N8N_CALENDAR_TOKEN');
}

const inp = raw.body || raw;
const confirmado = String(inp.confirmado_por_owner || '').toLowerCase() === 'true';
if (!confirmado) {
  throw new Error('CONFIRMACION_REQUERIDA: cancelar borra el evento del calendario real de Alek. Requiere confirmacion del owner.');
}

let rawRes = inp.resources;
if (typeof rawRes === 'string') {
  try { rawRes = JSON.parse(rawRes); } catch (e) { rawRes = rawRes.split(',').map(s => s.trim()); }
}
if (!Array.isArray(rawRes) || rawRes.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources es obligatorio y debe ser un array no vacio de "calendar" y/o "zoom".');
}
const validSet = new Set(['calendar', 'zoom']);
for (const r of rawRes) {
  if (!validSet.has(r)) {
    throw new Error(`RECURSOS_INVALIDOS: recurso desconocido "${r}". Solo se permite "calendar" y/o "zoom".`);
  }
}
const unique = Array.from(new Set(rawRes));
const resources = ['calendar', 'zoom'].filter(r => unique.includes(r));
if (resources.length === 0) {
  throw new Error('RECURSOS_INVALIDOS: resources no contiene recursos validos.');
}

const needCalendar = resources.includes('calendar');
const needZoom = resources.includes('zoom');

const eventoId = String(inp.evento_id || inp.event_id || inp.calendarEventId || '').trim();
const zoomId = String(inp.zoom_id || inp.zoom_meeting_id || inp.zoomMeetingId || '').trim();
const opId = String(inp.operation_id || inp.proposal_id || '').trim();

if (needCalendar && !eventoId) {
  throw new Error('FALTA_EVENTO: evento_id es obligatorio para cancelar recurso calendar.');
}
if (needZoom && !zoomId) {
  throw new Error('FALTA_ZOOM_ID: zoom_id es obligatorio para cancelar recurso zoom.');
}

return [{
  json: {
    resources,
    calendarEventId: eventoId || null,
    zoomMeetingId: zoomId || null,
    operation_id: opId || null
  }
}];

const prep = $('Preparar Cancelacion').first().json;
const respuestaRaw = $('Cancelar Calendar y Zoom').first().json || {};
const rawBody = respuestaRaw.body || respuestaRaw;
const dbRow = $input.first() ? ($input.first().json || {}) : {};

const resources = prep.resources || rawBody.resources || [];
const components = rawBody.components || {};
const providerVerified = rawBody.ok === true && rawBody.verified === true;
const dbModified = Boolean(dbRow && dbRow.token);
const verified = Boolean(providerVerified && dbModified);

return [{
  json: {
    ok: verified,
    verified,
    state: verified ? 'cancelada' : (providerVerified ? 'incierta' : 'no_cancelada'),
    estado: verified ? 'cancelada' : 'no_cancelada',
    resources,
    components,
    event_id: prep.calendarEventId || null,
    zoom_id: prep.zoomMeetingId || null,
    enlace_retirado: dbModified && dbRow.op === 'deleted',
    enlace_actualizado: dbModified && dbRow.op === 'updated',
    db_modified: dbModified,
    provider_verified: providerVerified
  }
}];

const rawResp = $input.first() ? ($input.first().json || {}) : {};
const raw = rawResp.body || rawResp;
const prep = $('Preparar Cancelacion').first()?.json || {};

return [{
  json: {
    ok: false,
    verified: false,
    state: 'no_cancelada',
    estado: 'no_cancelada',
    resources: prep.resources || [],
    components: raw.components || {},
    error: raw.error || 'El proveedor no pudo verificar la cancelacion de los recursos solicitados.',
    enlace_retirado: false,
    db_modified: false
  }
}];
